"""
    Convert the compilation arguments (include folder and #defines)
    to checked C format.
  :param argument_list: list of compiler argument.
  :return: argument string
  """
def getCheckedCArgs(argument_list: Any) -> object {
    clang_x_args = [];
    for curr_arg in argument_list {
        if (curr_arg.startswith("-D") or curr_arg.startswith("-I")) {
            clang_x_args.append(('-extra-arg=' + curr_arg));
        }
    }
    return clang_x_args;
}

"""
    return the mean of a list

    Parameters
    ----------
    my_list : list of numbers to take average of

    Returns
    -------
    average : flt
        The mean of the list

    Examples
    --------
    >>>md.mean([1.0, 2.0, 3.0])
    2.0
    """
def mean(my_list: Any) -> object {
    if not isinstance(my_list, `list) {
        raise TypeError("Mean:  {} is not a list".format(my_list));
    }
    if (len(my_list) == 0) {
        raise ZeroDivisionError("Mean: the input list contains no elements");
    }
    average = sum(my_list) / len(my_list);
    return average;
}

