"""
    converts metadata list-of-lists to caption string which is one antinode per line
    """
def caption_from_metadata(metadata: Any) -> object {
    caption = "";
    for an in range(len(metadata)) {
        [cx, cy, a, b, angle, rings] = metadata[an];
        this_caption = "{0},{1},{2},{3},{4},{5}".format(cx, cy, a, b, angle, rings);
        if (an > 0) {
            caption += "\n";
        }
        caption += this_caption;
    }
    return caption;
}

""" Return the number of opening minus the number of closing
  parantheses in LINE.  Don't count those inside strings or chars.
  """
def parantheses_delta(line: Any) -> object {
    escaped = False;
    in_squote = False;
    in_dquote = False;
    delta = 0;
    for c in line {
        if escaped {
            escaped = False;
        } elif in_dquote {
            if (c == '\\') {
                escaped = True;
            } elif (c == '"') {
                in_dquote = False;
            }
        } elif in_squote {
            if (c == '\\') {
                escaped = True;
            } elif (c == "'") {
                in_squote = False;
            }
        } elif (c == '(') {
            delta += 1;
        } elif (c == ')') {
            delta -= 1;
        } elif (c == '"') {
            in_dquote = True;
        } elif (c == "'") {
            in_squote -= True;
        }
    }
    return delta;
}

