"""returns a list of the elements that are
    not in common"""
def drop_matches(list1: Any, list2: Any) -> object {
    list1.sort();
    list2.sort();
    matches = [];
    i = j=0;
    lenLst1 = len(list1);
    lenLst2 = len(list2);
    while ((i < lenLst1) and (j < lenLst2)) {
        if (list1[i] < list2[j]) {
            matches.append(list1[i]);
            i += 1;
        } elif (list1[i] > list2[j]) {
            matches.append(list2[j]);
            j += 1;
        } else {
            i += 1;
            j += 1;
        }
    }
    while (i < lenLst1) {
        matches.append(list1[i]);
        i += 1;
    }
    while (j < lenLst2) {
        matches.append(list2[j]);
        j += 1;
    }
    return (len(matches), matches);
}

"""
    Helper function to the Evaluator.to_property_di_graph() method that
    packages the dictionaries returned by the "associate" family of
    functions and then supplies the master dict (one_dict) to the Vertex
    obj as kwargs.
    """
def build_dict(arg: Any) -> object {
    one_dict = {};
    for ar in arg {
        one_dict.update(ar);
    }
    return one_dict;
}

"""Given a list of Item rule triggers, extract the names of the Items and
    return them in a list.

    Arguments:
        - triggers: the list of rule trigger strings.
    Returns:
        A list of item_names.
    """
def get_items_from_triggers(triggers: Any) -> object {
    return [
        t.split(" ")[1]
        for t in triggers
        if t.startswith("Item")
    ];
}
